package net.officefloor.hq.app.patron;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.AsOfGuard;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.ResponseStatus;

@RestController
@Validated
public class PatronController {

    /** A patron named: the person who named them and the person named, by id. */
    public record PatronView(long id, long personId, long patronId) {
        static PatronView of(Patron patron) {
            return new PatronView(patron.getId(), patron.getPersonId(), patron.getPatronId());
        }
    }

    /** The patron form: the id of the person to name as patron. */
    public record PatronForm(@NotNull Long patronId) {
    }

    private final PatronService service;

    public PatronController(PatronService service) {
        this.service = service;
    }

    @GetMapping("/api/sheets/{sheetId}/patrons")
    public List<PatronView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        return service.list(sheetId.trim()).stream()
                .filter(p -> asOf == null || p.getNamedOn() == null || !p.getNamedOn().isAfter(asOf))
                .map(PatronView::of).toList();
    }

    @PostMapping("/api/sheets/{sheetId}/people/{personId}/patrons")
    @ResponseStatus(HttpStatus.CREATED)
    public PatronView add(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PatronForm form) {
        return PatronView.of(service.add(sheetId.trim(), user.trim(), personId, form.patronId()));
    }
}
package net.officefloor.hq.app.patron;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A patron of a person: another person on the same sheet they have named. */
@Entity
@Table(name = "patron")
public class Patron {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "patron_id", nullable = false)
    private Long patronId;

    /** The sheet's today when the patron was named; null for one named before it was kept. */
    @Column(name = "named_on")
    private LocalDate namedOn;

    protected Patron() {
    }

    public Patron(String sheetId, Long personId, Long patronId, LocalDate namedOn) {
        this.namedOn = namedOn;
        this.sheetId = sheetId;
        this.personId = personId;
        this.patronId = patronId;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public LocalDate getNamedOn() {
        return namedOn;
    }

    public Long getPatronId() {
        return patronId;
    }
}
package net.officefloor.hq.app.patron;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PatronRepository extends JpaRepository<Patron, Long> {

    /** The patrons named on a sheet in the order they were named. */
    List<Patron> findBySheetIdOrderByIdAsc(String sheetId);

    /** Whether the person has already named the patron. */
    boolean existsByPersonIdAndPatronId(Long personId, Long patronId);
}
package net.officefloor.hq.app.patron;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The patrons people on a sheet have named. */
@Service
public class PatronService {

    private final PatronRepository patrons;
    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public PatronService(PatronRepository patrons, PersonRepository people, SheetService sheets, Audit audit) {
        this.sheets = sheets;
        this.patrons = patrons;
        this.people = people;
        this.audit = audit;
    }

    /** The patrons named on the sheet in the order they were named. */
    @Transactional(readOnly = true)
    public List<Patron> list(String sheetId) {
        return patrons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Name another person on the sheet as a person's patron; refused for the person themselves and
     *  for a patron they have already named. */
    @Transactional
    public Patron add(String sheetId, String user, long personId, long patronId) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron on this sheet"));
        if (person.getId().equals(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A person cannot be their own patron");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw alreadyNamed();
        }
        Patron saved;
        try {
            saved = patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId(), sheets.today(sheetId)));
        } catch (DataIntegrityViolationException e) {
            throw alreadyNamed();
        }
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " patron=" + patron.getName());
        return saved;
    }

    private static ResponseStatusException alreadyNamed() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That patron is already named");
    }
}
-- A person's patrons: other people on the same sheet they have named, each at most once.
CREATE TABLE patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CONSTRAINT patron_not_self CHECK (person_id <> patron_id),
    CONSTRAINT patron_unique UNIQUE (person_id, patron_id)
);
CREATE INDEX patron_sheet ON patron (sheet_id, id);
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

/** A patron named: the person who named them and the person named, by id. */
export interface Patron {
  id: number;
  personId: number;
  patronId: number;
}

// The patrons people on the active sheet have named.
@Injectable({ providedIn: 'root' })
export class Patrons {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The patrons named on the sheet in the order they were named. */
  list(sheetId: string): Promise<Patron[]> {
    return firstValueFrom(this.http.get<Patron[]>(`/api/sheets/${encodeURIComponent(sheetId)}/patrons`));
  }

  /** Name another person as the person's patron; refused for the person themselves and for a
   *  patron they have already named. */
  add(personId: number, patronId: number): Promise<Patron> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<Patron>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/patrons`, { patronId },
        { headers: { 'X-User': user } }),
    );
  }
}
